static char *operation(const char *op,const char *id,const char *name){char *out=NULL;size_t n;FILE *stream=open_memstream(&out,&n);CHECK(stream);fprintf(stream,"{\"contract_version\":1,\"op\":\"%s\",\"plan_id\":\"%s\"",op,id);if(name)fprintf(stream,",\"operation_id\":\"%s\",\"plan_revision\":1",name);fputc('}',stream);CHECK(!fclose(stream));return out;}
static char *create(const char *root,const char *name,const char *source,const char *destination){char path[2048],id[65],version[65];snprintf(path,sizeof(path),"%s/%s",root,source);struct stat info;CHECK(!stat(path,&info));
#ifdef __APPLE__
    long nanos=info.st_mtimespec.tv_nsec;
#else
    long nanos=info.st_mtim.tv_nsec;
#endif
    char metadata[256];int n=snprintf(metadata,sizeof(metadata),"file-identity-v1:%llu:%llu:%llu:%lld:%ld",(unsigned long long)info.st_dev,(unsigned long long)info.st_ino,(unsigned long long)info.st_size,(long long)info.st_mtime,nanos);hash_bytes(metadata,(size_t)n,id);FILE *in=fopen(path,"r");CHECK(in);char content[1024];size_t length=fread(content,1,sizeof(content),in);CHECK(!fclose(in));hash_bytes(content,length,version);char *out=NULL;size_t bytes;FILE *stream=open_memstream(&out,&bytes);CHECK(stream);fprintf(stream,"{\"contract_version\":1,\"op\":\"plan_create\",\"operation_id\":\"%s\",\"action\":\"copy\",\"host_id\":\"local-endpoint\",\"files\":[{\"source\":",name);json_quote(stream,source,strlen(source));fputs(",\"destination\":",stream);json_quote(stream,destination,strlen(destination));fprintf(stream,",\"version\":\"%s\",\"file_identity\":\"%s\"}]}",version,id);CHECK(!fclose(stream));return out;}
