    char fixture[]="/tmp/samosa-native-actions-XXXXXX";CHECK(mkdtemp(fixture));char root[1024],state[1024],path[2048],destination[2048],marker[1024];snprintf(root,sizeof(root),"%s/root",fixture);snprintf(state,sizeof(state),"%s/state",fixture);CHECK(!mkdir(root,0700));snprintf(path,sizeof(path),"%s/source.txt",root);file(path,"code7319");snprintf(destination,sizeof(destination),"%s/copy.txt",root);AgentConfig cfg={.state=state,.action_root=root};
    char *input=create(root,"create-copy","source.txt","copy.txt"),*first=call(&cfg,input,0),*plan=field(first,"plan_id");AgentConfig offline=cfg;offline.action_root=NULL;char *out=call(&offline,input,0);CHECK(!strcmp(first,out));free(out);free(first);free(input);
