    input=operation("plan_get",plan,NULL);out=call(&cfg,input,0);CHECK(strstr(out,"\"copied_items\":0"));CHECK(strstr(out,"\"unreconciled_items\":1"));free(out);char *crash_retry=operation("plan_execute",plan,"crashed-copy");out=call(&offline,crash_retry,0);CHECK(strstr(out,"\"status\":\"running\""));free(out);CHECK(!kill(worker,SIGKILL));int status;CHECK(waitpid(worker,&status,0)==worker);CHECK(WIFSIGNALED(status)&&WTERMSIG(status)==SIGKILL);out=call(&offline,crash_retry,0);CHECK(strstr(out,"interrupted"));free(out);free(crash_retry);out=call(&cfg,input,0);CHECK(strstr(out,"\"copied_items\":1"));CHECK(strstr(out,"published_inode"));free(out);free(input);
    input=operation("plan_execute",plan,"crashed-copy");out=call(&offline,input,0);CHECK(strstr(out,"interrupted"));free(out);free(input);input=operation("plan_execute",plan,"resume");first=call(&cfg,input,0);CHECK(strstr(first,"\"copied_items\":1"));out=call(&offline,input,0);CHECK(!strcmp(first,out));free(out);free(first);free(input);struct stat after;CHECK(!stat(destination,&after));CHECK(after.st_ino==published.st_ino);assert_file(path,"code7319");
    AgentConfig stranger=cfg;stranger.owner="other-owner";input=operation("plan_get",plan,NULL);out=call(&stranger,input,1);CHECK(strstr(out,"unknown_plan"));free(out);free(input);free(plan);
    input=create(root,"stale-create","source.txt","stale.txt");out=call(&cfg,input,0);plan=field(out,"plan_id");free(out);free(input);input=operation("plan_approve",plan,"stale-approve");out=call(&cfg,input,0);free(out);free(input);file(path,"changed after approval");input=operation("plan_execute",plan,"stale-execute");out=call(&cfg,input,0);CHECK(strstr(out,"stale_source"));CHECK(strstr(out,"\"failed_items\":1"));free(out);free(input);free(plan);
    input=create(root,"foreign-create","source.txt","foreign.txt");out=call(&cfg,input,0);plan=field(out,"plan_id");free(out);free(input);input=operation("plan_approve",plan,"foreign-approve");out=call(&cfg,input,0);free(out);free(input);snprintf(destination,sizeof(destination),"%s/foreign.txt",root);file(destination,"unrelated-file");input=operation("plan_execute",plan,"foreign-execute");out=call(&cfg,input,0);CHECK(strstr(out,"destination_exists"));free(out);free(input);assert_file(destination,"unrelated-file");free(plan);
    input=create(root,"escape","source.txt","../outside.txt");out=call(&cfg,input,1);CHECK(strstr(out,"invalid_plan"));free(out);free(input);snprintf(destination,sizeof(destination),"%s/link",root);CHECK(!symlink("/tmp",destination));input=create(root,"symlink","source.txt","link/outside.txt");out=call(&cfg,input,1);CHECK(strstr(out,"destination_unavailable"));free(out);free(input);
    /* A foreign replacement after publication must never be adopted as a receipt. */
    input=create(root,"replacement-create","source.txt","replacement.txt");out=call(&cfg,input,0);plan=field(out,"plan_id");free(out);free(input);input=operation("plan_approve",plan,"replacement-approve");out=call(&cfg,input,0);free(out);free(input);CHECK(!unlink(marker));CHECK(!setenv("SAMOSA_ACTION_TEST_PUBLISHED_MARKER",marker,1));char *replacement_args[]={argv[0],"--worker",state,root,plan,"replacement-crash",NULL};CHECK(!posix_spawnp(&worker,argv[0],NULL,NULL,replacement_args,environ));CHECK(!unsetenv("SAMOSA_ACTION_TEST_PUBLISHED_MARKER"));ready=0;for(int i=0;i<500;i++){if(!access(marker,F_OK)){ready=1;break;}struct timespec delay={0,10000000};nanosleep(&delay,NULL);}CHECK(ready);CHECK(!kill(worker,SIGKILL));CHECK(waitpid(worker,&status,0)==worker);snprintf(destination,sizeof(destination),"%s/replacement.txt",root);CHECK(!unlink(destination));file(destination,"foreign replacement");input=operation("plan_get",plan,NULL);out=call(&cfg,input,0);CHECK(strstr(out,"destination_changed"));CHECK(strstr(out,"\"copied_items\":0"));CHECK(strstr(out,"\"failed_items\":1"));free(out);free(input);assert_file(destination,"foreign replacement");free(plan);
    input=create(root,"parent-create","source.txt","source-parent-protected.txt");out=call(&cfg,input,0);plan=field(out,"plan_id");free(out);free(input);input=operation("plan_approve",plan,"root-approve");out=call(&cfg,input,0);free(out);free(input);char old_root[1024];snprintf(old_root,sizeof(old_root),"%s/old-root",fixture);CHECK(!rename(root,old_root));CHECK(!mkdir(root,0700));input=operation("plan_execute",plan,"changed-root");out=call(&cfg,input,1);CHECK(strstr(out,"stale_scope"));free(out);free(input);CHECK(!rmdir(root));CHECK(!rename(old_root,root));free(plan);
    snprintf(destination,sizeof(destination),"%s/target",root);CHECK(!mkdir(destination,0700));input=create(root,"parent-directory-create","source.txt","target/protected.txt");out=call(&cfg,input,0);plan=field(out,"plan_id");free(out);free(input);input=operation("plan_approve",plan,"parent-directory-approve");out=call(&cfg,input,0);free(out);free(input);char old_directory[2048];snprintf(old_directory,sizeof(old_directory),"%s/old-target",root);CHECK(!rename(destination,old_directory));CHECK(!mkdir(destination,0700));input=operation("plan_execute",plan,"changed-parent");out=call(&cfg,input,0);CHECK(strstr(out,"stale_destination_scope"));free(out);free(input);snprintf(destination,sizeof(destination),"%s/target/protected.txt",root);CHECK(access(destination,F_OK)!=0);free(plan);
